import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { build } from 'esbuild';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const vendorRoot = resolve(root, 'frontend/vendored');
const importMap = JSON.parse(readFileSync(resolve(vendorRoot, 'importmap.json'), 'utf8')).imports;
const aliases = new Map(Object.entries(importMap).map(([specifier, target]) => (
    [specifier, resolve(vendorRoot, target)]
)));
for (const [specifier, target] of Object.entries({
    '@replit/codemirror-vim': '@replit/codemirror-vim/dist/index.js',
    '@replit/codemirror-indentation-markers': '@replit/codemirror-indentation-markers/dist/index.js',
    'codemirror-live-markdown': 'codemirror-live-markdown/index.js',
})) aliases.set(specifier, resolve(vendorRoot, target));

const prefixes = [...aliases.entries()].filter(([specifier]) => specifier.endsWith('/'));
const vendorImportMapPlugin = {
    name: 'figaro-vendor-import-map',
    setup(builder) {
        builder.onResolve({ filter: /^[^./]|^\// }, args => {
            const exact = aliases.get(args.path);
            if (exact) return { path: exact };
            for (const [specifier, target] of prefixes) {
                if (args.path.startsWith(specifier)) {
                    return { path: resolve(target, args.path.slice(specifier.length)) };
                }
            }
            return null;
        });
    },
};

await build({
    absWorkingDir: root,
    entryPoints: ['frontend/js/bootstrap.js'],
    outfile: 'frontend/app.bundle.js',
    bundle: true,
    minify: true,
    format: 'esm',
    platform: 'browser',
    target: 'es2020',
    legalComments: 'none',
    plugins: [vendorImportMapPlugin],
    banner: { js: '/* Generated by scripts/build-app-bundle.mjs. Do not edit directly. */' },
});

for (const [source, target] of [['writingWorker', 'writing'], ['writingSpellingWorker', 'spelling'], ['writingDecisionWorker', 'decisions'], ['activityWorker', 'activity']]) {
    await build({
        absWorkingDir: root, entryPoints: [`frontend/js/${source}.js`], outfile: `frontend/${target}.worker.js`,
        bundle: true, minify: true, format: 'esm', platform: 'browser', target: 'es2020',
        legalComments: 'eof', plugins: [vendorImportMapPlugin],
    });
}
